<?php require 'app.php';need_owner();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{if(($_POST['action']??'')==='status'){if(!in_array($_POST['status']??'', ['active','suspended','pending','rejected'],true))throw new RuntimeException('Invalid school status.');db()->prepare('UPDATE schools SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['school_id']]);$msg='School status updated.';}elseif(($_POST['action']??'')==='subscription'){if(!in_array($_POST['plan']??'', ['none','monthly','yearly','custom'],true)||!in_array($_POST['subscription_status']??'', ['none','trial','active','past_due','expired','cancelled'],true))throw new RuntimeException('Invalid subscription values.');db()->prepare('UPDATE schools SET subscription_plan=?,subscription_status=? WHERE id=?')->execute([$_POST['plan'],$_POST['subscription_status'],(int)$_POST['school_id']]);$msg='Subscription details updated.';}else{$name=trim($_POST['name']);$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$_POST['slug']?:$name),'-'));$email=strtolower(trim($_POST['director_email']));$pw=$_POST['director_password'];if(strlen($pw)<10)throw new RuntimeException('Director password must contain at least 10 characters.');$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO schools(name,slug,email,phone,address,status) VALUES(?,?,?,?,?,'active') RETURNING id");$q->execute([$name,$slug,$_POST['email']?:null,$_POST['phone']?:null,$_POST['address']?:null]);$sid=(int)$q->fetchColumn();$q=$pdo->prepare('INSERT INTO users(full_name,email,password_hash) VALUES(?,?,?) ON CONFLICT(email) DO UPDATE SET full_name=EXCLUDED.full_name RETURNING id');$q->execute([trim($_POST['director_name']),$email,password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO memberships(school_id,user_id,role_key) VALUES(?,?,'director') ON CONFLICT(school_id,user_id) DO UPDATE SET role_key='director'");$q->execute([$sid,$uid]);$pdo->prepare('INSERT INTO school_settings(school_id) VALUES(?) ON CONFLICT DO NOTHING')->execute([$sid]);$pdo->commit();$msg='School and Director account created successfully.';}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$msg=$e->getMessage();}}$rows=db()->query('SELECT s.*, (SELECT count(*) FROM students st WHERE st.school_id=s.id) student_count FROM schools s ORDER BY s.id DESC')->fetchAll();ob_start();?><div class="panel"><h2>Register a school</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><div class="grid"><label>School name<input name="name" required></label><label>School slug<input name="slug" placeholder="auto from name"></label><label>School email<input name="email" type="email"></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label></div><h3>First School Director</h3><div class="grid"><label>Full name<input name="director_name" required></label><label>Email<input name="director_email" type="email" required></label><label>Temporary password (10+ characters)<input name="director_password" minlength="10" required></label></div><button>Create school</button></form><?php if($msg):?><p><?=h($msg)?></p><?php endif;?></div><div class="panel"><h2>Registered schools</h2><table><tr><th>School</th><th>Status</th><th>Students</th><th>School status</th><th>Subscription</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['status'])?></td><td><?=$r['student_count']?></td><td><form method="post" style="display:flex;gap:6px"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="school_id" value="<?=$r['id']?>"><select name="status"><option value="active" <?=$r['status']==='active'?'selected':''?>>Active</option><option value="suspended" <?=$r['status']==='suspended'?'selected':''?>>Suspended</option><option value="pending" <?=$r['status']==='pending'?'selected':''?>>Pending</option><option value="rejected" <?=$r['status']==='rejected'?'selected':''?>>Rejected</option></select><button>Save</button></form></td><td><form method="post" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="subscription"><input type="hidden" name="school_id" value="<?=$r['id']?>"><select name="plan"><option value="none" <?=$r['subscription_plan']==='none'?'selected':''?>>No plan</option><option value="monthly" <?=$r['subscription_plan']==='monthly'?'selected':''?>>Monthly</option><option value="yearly" <?=$r['subscription_plan']==='yearly'?'selected':''?>>Yearly</option><option value="custom" <?=$r['subscription_plan']==='custom'?'selected':''?>>Custom</option></select><select name="subscription_status"><option value="none" <?=$r['subscription_status']==='none'?'selected':''?>>None</option><option value="trial" <?=$r['subscription_status']==='trial'?'selected':''?>>Trial</option><option value="active" <?=$r['subscription_status']==='active'?'selected':''?>>Active</option><option value="past_due" <?=$r['subscription_status']==='past_due'?'selected':''?>>Past due</option><option value="expired" <?=$r['subscription_status']==='expired'?'selected':''?>>Expired</option><option value="cancelled" <?=$r['subscription_status']==='cancelled'?'selected':''?>>Cancelled</option></select><button>Save</button></form></td></tr><?php endforeach;?></table></div><?php page('Platform Schools',ob_get_clean());
